from g123_core import make_q, make_lesson
from fig_helpers_g123 import table_fig, bars_fig, fig_music_staff


def _q(b, num, d, p, c, w, e, s='', h='', fig=None):
    return make_q(f'AN2-B{b:02d}-{num:03d}', d, p, c, w, e, s, h, fig)


